<!-- WARNING: 本项目专属“粘人精”，严禁出现 Kiro、Krio、周棋洛等任何相关英文或拼音命名！ -->
<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { globalSettings } from '../../store/global'
import { getSecureValue, isNativeMobileApp, setSecureValue } from '../../services/mobileSecureStorage'
import { downloadWebVideo, type VideoConnectionMode } from '../../services/videoHttp'
import {
  ATLAS_DEFAULT_BASE_URL, ATLAS_VIDEO_MODELS, AtlasApiError, buildAtlasBody, downloadAtlasVideo,
  estimateAtlasCost, findAtlasPreset, getAtlasBalance, queryAtlasVideo, removeAtlasVideoFile,
  shareAtlasVideo, submitAtlasVideo, uploadAtlasMedia, validateAtlasInput,
  type AtlasCostEstimate, type AtlasModelPreset, type AtlasVideoInput, type AtlasWorkflow
} from '../../services/atlasCloudVideo'
import { useAtlasCloudVideoHistory, type AtlasLocalTask } from '../../composables/useAtlasCloudVideoHistory'

defineEmits<{(event:'back'):void}>()
const nativeApp=isNativeMobileApp()
const read=(key:string,fallback:string)=>localStorage.getItem(key)||fallback
const connectionMode=ref<VideoConnectionMode>((nativeApp?read('app_atlas_connection_mode','app'):'web') as VideoConnectionMode)
const rememberKey=ref(read('app_atlas_remember_key','false')==='true')
const apiKey=ref(rememberKey.value?read('app_atlas_web_api_key',''):'')
const webSessionKey=ref(apiKey.value)
const keyReady=ref(false)
const showKey=ref(false)
const settingsOpen=ref(false)
const advancedOpen=ref(false)
const modelCenterOpen=ref(false)
const activeTab=ref<'create'|'works'>('create')
const notice=ref('')
const errorText=ref('')
const busy=ref(false)
const estimating=ref(false)
const uploading=ref(false)
const estimate=ref<AtlasCostEstimate|null>(null)
const balance=ref<{value:number;currency:string}|null>(null)
const confirmInput=ref<AtlasVideoInput|null>(null)
const deletingTask=ref<AtlasLocalTask|null>(null)
const search=ref('')
const providerFilter=ref('全部')
const workflowFilter=ref<'全部'|AtlasWorkflow>('全部')
const favorites=ref<string[]>(readFavorites())
const favoritesOnly=ref(false)
const customModel=ref(read('app_atlas_custom_model',''))
const customWorkflow=ref<AtlasWorkflow>((read('app_atlas_custom_workflow','text') as AtlasWorkflow))
const selectedModel=ref(read('app_atlas_model',ATLAS_VIDEO_MODELS[0].id))
const project=ref(read('app_atlas_project','默认作品集'))
const projectFilter=ref('全部')
const prompt=ref(read('app_atlas_prompt',''))
const sourceUrls=ref<string[]>(readSources())
const extraJson=ref(read('app_atlas_extra_json','{}'))
const pollers=new Map<string,AbortController>()

const config=reactive({
  baseUrl:read('app_atlas_base_url',ATLAS_DEFAULT_BASE_URL),
  duration:Number(read('app_atlas_duration','5')),
  resolution:read('app_atlas_resolution','720p'),
  ratio:read('app_atlas_ratio','16:9'),
  seed:read('app_atlas_seed',''),
  promptExpansion:read('app_atlas_prompt_expansion','true')!=='false',
  watermark:read('app_atlas_watermark','false')==='true',
  objectExpirationHours:Number(read('app_atlas_object_expiration','336')),
  requestRetentionHours:Number(read('app_atlas_request_retention','336'))
})
const {tasks,load,save,patch,get,remove}=useAtlasCloudVideoHistory()

function readFavorites(){try{const value=JSON.parse(read('app_atlas_favorites','[]'));return Array.isArray(value)?value.filter(item=>typeof item==='string'):[]}catch{return []}}
function readSources(){try{const value=JSON.parse(read('app_atlas_sources','[]'));return Array.isArray(value)?value.filter(item=>typeof item==='string'):[]}catch{return []}}
const clearFeedback=()=>{notice.value='';errorText.value=''}
const selectedPreset=computed(()=>findAtlasPreset(selectedModel.value))
const workflow=computed<AtlasWorkflow>(()=>selectedPreset.value?.workflow||customWorkflow.value)
const providers=computed(()=>['全部',...Array.from(new Set(ATLAS_VIDEO_MODELS.map(item=>item.provider)))])
const visibleModels=computed(()=>{
  const query=search.value.trim().toLowerCase()
  return ATLAS_VIDEO_MODELS.filter(item=>(providerFilter.value==='全部'||item.provider===providerFilter.value)&&(workflowFilter.value==='全部'||item.workflow===workflowFilter.value)&&(!favoritesOnly.value||favorites.value.includes(item.id))&&(!query||`${item.name} ${item.id} ${item.provider} ${item.description} ${item.tags.join(' ')}`.toLowerCase().includes(query)))
})
const projectNames=computed(()=>Array.from(new Set(tasks.value.map(item=>item.project||'默认作品集'))))
const visibleTasks=computed(()=>projectFilter.value==='全部'?tasks.value:tasks.value.filter(item=>(item.project||'默认作品集')===projectFilter.value))
const activeTasks=computed(()=>tasks.value.filter(item=>['submitting','queued','processing','downloading'].includes(item.status)))
const canGenerate=computed(()=>keyReady.value&&Boolean(apiKey.value.trim())&&(connectionMode.value==='web'||nativeApp)&&!busy.value&&!uploading.value)
const modelLabel=(model:string)=>findAtlasPreset(model)?.name||model
const currentModelId=computed(()=>selectedModel.value==='custom'?customModel.value.trim():selectedModel.value)
const outputUsable=(task:AtlasLocalTask)=>Boolean(task.outputUrl&&(!task.outputExpiresAt||task.outputExpiresAt>Date.now()))

const parseExtra=()=>{try{const value=JSON.parse(extraJson.value||'{}');if(!value||Array.isArray(value)||typeof value!=='object')throw new Error();return value as Record<string,unknown>}catch{throw new Error('模型专属参数必须是有效的 JSON 对象')}}
const buildInput=():AtlasVideoInput=>({
  model:currentModelId.value,prompt:prompt.value,workflow:workflow.value,duration:config.duration||undefined,
  resolution:config.resolution||undefined,ratio:config.ratio||undefined,sourceUrls:workflow.value==='text'?[]:sourceUrls.value.filter(Boolean),
  seed:config.seed===''?undefined:Number(config.seed),promptExpansion:config.promptExpansion,watermark:config.watermark,
  extra:parseExtra(),objectExpirationHours:config.objectExpirationHours,requestRetentionHours:config.requestRetentionHours
})
const client=()=>({apiKey:apiKey.value,baseUrl:config.baseUrl,connectionMode:connectionMode.value})
const taskClient=(task:AtlasLocalTask)=>({apiKey:apiKey.value,baseUrl:task.baseUrl,connectionMode:task.connectionMode})

watch([connectionMode,rememberKey],()=>{localStorage.setItem('app_atlas_connection_mode',connectionMode.value);localStorage.setItem('app_atlas_remember_key',String(rememberKey.value));if(!rememberKey.value)localStorage.removeItem('app_atlas_web_api_key')})
watch(apiKey,value=>{if(connectionMode.value!=='web')return;webSessionKey.value=value;if(rememberKey.value)localStorage.setItem('app_atlas_web_api_key',value)})
watch(connectionMode,async value=>{clearFeedback();apiKey.value=value==='web'?(rememberKey.value?read('app_atlas_web_api_key',webSessionKey.value):webSessionKey.value):nativeApp?(await getSecureValue('atlas_cloud_api_key'))||'':''})
watch(prompt,value=>localStorage.setItem('app_atlas_prompt',value))
watch(project,value=>localStorage.setItem('app_atlas_project',value))
watch(customModel,value=>localStorage.setItem('app_atlas_custom_model',value))
watch(customWorkflow,value=>{localStorage.setItem('app_atlas_custom_workflow',value);if(selectedModel.value==='custom'){sourceUrls.value=value==='text'?[]:sourceUrls.value.length?sourceUrls.value:[''];estimate.value=null}})
watch(sourceUrls,value=>localStorage.setItem('app_atlas_sources',JSON.stringify(value)),{deep:true})
watch(extraJson,value=>localStorage.setItem('app_atlas_extra_json',value))
watch(favorites,value=>localStorage.setItem('app_atlas_favorites',JSON.stringify(value)),{deep:true})
watch(config,value=>{localStorage.setItem('app_atlas_base_url',value.baseUrl);localStorage.setItem('app_atlas_duration',String(value.duration));localStorage.setItem('app_atlas_resolution',value.resolution);localStorage.setItem('app_atlas_ratio',value.ratio);localStorage.setItem('app_atlas_seed',value.seed);localStorage.setItem('app_atlas_prompt_expansion',String(value.promptExpansion));localStorage.setItem('app_atlas_watermark',String(value.watermark));localStorage.setItem('app_atlas_object_expiration',String(value.objectExpirationHours));localStorage.setItem('app_atlas_request_retention',String(value.requestRetentionHours))},{deep:true})

const chooseModel=(item:AtlasModelPreset)=>{selectedModel.value=item.id;localStorage.setItem('app_atlas_model',item.id);config.duration=item.duration;config.resolution=item.resolution;config.ratio=item.ratio;if(item.workflow==='text')sourceUrls.value=[];else if(!sourceUrls.value.length)sourceUrls.value=[''];estimate.value=null;modelCenterOpen.value=false;clearFeedback()}
const chooseCustom=()=>{selectedModel.value='custom';localStorage.setItem('app_atlas_model','custom');modelCenterOpen.value=false;estimate.value=null;clearFeedback()}
const toggleFavorite=(id:string)=>{favorites.value=favorites.value.includes(id)?favorites.value.filter(item=>item!==id):[...favorites.value,id]}
const addSource=()=>{if(sourceUrls.value.length<8)sourceUrls.value.push('')}
const removeSource=(index:number)=>sourceUrls.value.splice(index,1)
const randomSeed=()=>{config.seed=String(Math.floor(Math.random()*2147483647))}

const saveKey=async()=>{clearFeedback();if(!apiKey.value.trim()){errorText.value='请输入 Atlas Cloud API Key';return}try{if(connectionMode.value==='app'){if(!nativeApp)throw new Error('App 直连需要在安装后的 Android 或 iOS App 中使用');await setSecureValue('atlas_cloud_api_key',apiKey.value.trim())}else if(rememberKey.value)localStorage.setItem('app_atlas_web_api_key',apiKey.value.trim());notice.value=connectionMode.value==='app'?'密钥已保存到设备安全存储。':rememberKey.value?'密钥已保存在当前浏览器。':'密钥仅在当前页面会话中使用。'}catch(error){errorText.value=error instanceof Error?error.message:'密钥保存失败'}}
const refreshBalance=async()=>{clearFeedback();if(!apiKey.value.trim()){errorText.value='请先填写 API Key';return}try{balance.value=await getAtlasBalance(client());notice.value='余额已更新。'}catch(error){errorText.value=displayError(error)}}
const displayError=(error:unknown)=>{if(error instanceof AtlasApiError&&error.requestId)return `${error.message}（请求 ID：${error.requestId}）`;return error instanceof Error?error.message:'操作失败'}

const uploadLocal=async(event:Event)=>{const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;clearFeedback();uploading.value=true;try{const url=await uploadAtlasMedia(client(),file);const empty=sourceUrls.value.findIndex(value=>!value.trim());if(empty>=0)sourceUrls.value[empty]=url;else sourceUrls.value.push(url);notice.value=`${file.name} 已上传为临时素材，请尽快提交生成。`}catch(error){errorText.value=displayError(error)}finally{uploading.value=false}}
const calculate=async(input?:AtlasVideoInput)=>{clearFeedback();estimating.value=true;try{const value=input||buildInput();validateAtlasInput(value);estimate.value=await estimateAtlasCost(client(),value);notice.value='已按当前模型和参数更新费用。';return estimate.value}catch(error){errorText.value=displayError(error);return null}finally{estimating.value=false}}
const requestGenerate=async()=>{clearFeedback();try{const value=buildInput();validateAtlasInput(value);confirmInput.value=value;await calculate(value)}catch(error){confirmInput.value=null;errorText.value=displayError(error)}}
const confirmGenerate=async()=>{if(!confirmInput.value)return;const input=confirmInput.value;confirmInput.value=null;busy.value=true;clearFeedback();const id=`atlas_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;try{await save({id,status:'submitting',progress:0,createdAt:Date.now(),updatedAt:Date.now(),baseUrl:config.baseUrl,connectionMode:connectionMode.value,project:project.value.trim()||'默认作品集',input:JSON.parse(JSON.stringify(input)),estimate:estimate.value||undefined});const remote=await submitAtlasVideo(client(),input);if(!remote.id)throw new Error('Atlas Cloud 没有返回 prediction ID');await patch(id,{remoteId:remote.id,status:remote.status==='processing'?'processing':'queued',progress:remote.progress,requestId:remote.requestId});notice.value='任务已提交，可以在作品页查看进度。';activeTab.value='works';void pollTask(id)}catch(error){await patch(id,{status:'failed',error:displayError(error)}).catch(()=>undefined);errorText.value=displayError(error)}finally{busy.value=false}}

const wait=(ms:number,signal:AbortSignal)=>new Promise<void>((resolve,reject)=>{const timer=setTimeout(resolve,ms);signal.addEventListener('abort',()=>{clearTimeout(timer);reject(new DOMException('Aborted','AbortError'))},{once:true})})
const pollTask=async(id:string)=>{if(pollers.has(id))return;const controller=new AbortController();pollers.set(id,controller);let delay=3000;try{while(!controller.signal.aborted){const row=await get(id);if(!row?.remoteId)return;if(row.connectionMode!==connectionMode.value)throw new Error(`请切换到${row.connectionMode==='web'?'网页直连':'App 直连'}后继续查询`);const remote=await queryAtlasVideo(taskClient(row),row.remoteId);if(remote.status==='completed'){const output=remote.outputs[0];if(!output)throw new Error('任务已完成，但没有返回视频地址');const expires=(row.createdAt+(row.input.objectExpirationHours||336)*3600000);await patch(id,{status:connectionMode.value==='app'?'downloading':'completed',progress:100,outputUrl:output,outputExpiresAt:expires,requestId:remote.requestId||row.requestId,error:''});if(connectionMode.value==='app'){try{const local=await downloadAtlasVideo(row.remoteId,output);await patch(id,{status:'completed',localFilePath:local.path,localFileUri:local.uri,localWebUrl:local.webUrl})}catch(error){await patch(id,{status:'paused',error:`视频已生成，但自动保存失败：${displayError(error)}`})}}return}if(remote.status==='failed'||remote.status==='timeout'){await patch(id,{status:remote.status,progress:remote.progress,error:remote.error||`任务${remote.status==='timeout'?'超时':'失败'}`,errorCode:remote.errorCode,requestId:remote.requestId||row.requestId});return}await patch(id,{status:remote.status==='queued'?'queued':'processing',progress:remote.progress,requestId:remote.requestId||row.requestId,error:''});await wait(delay,controller.signal);delay=Math.min(Math.round(delay*1.5),10000)}}catch(error){if((error as Error)?.name!=='AbortError'){const current=await get(id);const retryable=error instanceof AtlasApiError&&error.retryable;await patch(id,{status:retryable?'paused':'failed',error:displayError(error)}).catch(()=>undefined)}}finally{pollers.delete(id)}}
const pauseTask=async(task:AtlasLocalTask)=>{pollers.get(task.id)?.abort();await patch(task.id,{status:'paused',error:'已暂停本机查询；云端任务不会取消，也不会因此退款。'})}
const resumeTask=async(task:AtlasLocalTask)=>{clearFeedback();if(task.connectionMode!==connectionMode.value){errorText.value=`请先切换到${task.connectionMode==='web'?'网页直连':'App 直连'}`;return}await patch(task.id,{status:'queued',error:''});void pollTask(task.id)}
const downloadTask=async(task:AtlasLocalTask)=>{clearFeedback();if(task.localFileUri){await shareAtlasVideo(task.localFileUri);return}if(!outputUsable(task)){errorText.value='远程视频地址已过期，无法继续下载。';return}if(connectionMode.value==='web'){downloadWebVideo(task.outputUrl!,`${task.remoteId||task.id}.mp4`);return}try{await patch(task.id,{status:'downloading',error:''});const local=await downloadAtlasVideo(task.remoteId||task.id,task.outputUrl!);await patch(task.id,{status:'completed',localFilePath:local.path,localFileUri:local.uri,localWebUrl:local.webUrl})}catch(error){await patch(task.id,{status:'paused',error:displayError(error)})}}
const reuseTask=(task:AtlasLocalTask)=>{selectedModel.value=findAtlasPreset(task.input.model)?task.input.model:'custom';customModel.value=findAtlasPreset(task.input.model)?customModel.value:task.input.model;prompt.value=task.input.prompt;sourceUrls.value=[...task.input.sourceUrls];config.duration=task.input.duration||5;config.resolution=task.input.resolution||'';config.ratio=task.input.ratio||'';config.seed=task.input.seed===undefined?'':String(task.input.seed);config.promptExpansion=task.input.promptExpansion??true;config.watermark=task.input.watermark??false;extraJson.value=JSON.stringify(task.input.extra||{},null,2);project.value=task.project;activeTab.value='create';notice.value='已复用作品参数，提交前可切换模型或修改内容。'}
const confirmDelete=async()=>{const task=deletingTask.value;if(!task)return;pollers.get(task.id)?.abort();await removeAtlasVideoFile(task.localFilePath);await remove(task.id);deletingTask.value=null;notice.value='本地作品记录已删除，Atlas Cloud 云端记录未被修改。'}
const statusLabel=(status:AtlasLocalTask['status'])=>({submitting:'正在提交',queued:'排队中',processing:'生成中',paused:'已暂停',downloading:'正在保存',completed:'已完成',failed:'生成失败',timeout:'任务超时'}[status])
const formatTime=(value:number)=>new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})
const formatPrice=(value?:AtlasCostEstimate|null)=>value?.price===undefined?'暂不可用':`${value.currency} ${value.price.toFixed(4)}${value.estimated?'（预估）':''}`

onMounted(async()=>{try{if(nativeApp&&connectionMode.value==='app')apiKey.value=(await getSecureValue('atlas_cloud_api_key'))||'';await load();keyReady.value=true;for(const task of tasks.value.filter(item=>['submitting','queued','processing','downloading'].includes(item.status))){if(task.remoteId&&task.connectionMode===connectionMode.value)void pollTask(task.id);else await patch(task.id,{status:'paused',error:`切换到${task.connectionMode==='web'?'网页直连':'App 直连'}后可继续查询。`})}}catch(error){errorText.value=displayError(error);keyReady.value=true}})
onUnmounted(()=>{pollers.forEach(controller=>controller.abort());pollers.clear()})
</script>

<template>
  <div class="atlas-hall" :class="{dark:globalSettings.darkMode}">
    <header class="hall-header"><button class="icon-button" aria-label="返回视频大厅" @click="$emit('back')"><svg viewBox="0 0 24 24"><path d="m15 18-6-6 6-6"/></svg></button><div class="header-copy"><h1>Atlas Cloud</h1><p>多模型统一创作中心</p></div><button class="icon-button" aria-label="连接设置" @click="settingsOpen=!settingsOpen"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1a1.7 1.7 0 0 0 1.9.3 1.7 1.7 0 0 0 1-1.6v-.2h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1Z"/></svg></button></header>
    <nav class="hall-tabs"><button :class="{active:activeTab==='create'}" @click="activeTab='create'">创作</button><button :class="{active:activeTab==='works'}" @click="activeTab='works'">作品 <span v-if="tasks.length">{{ tasks.length }}</span></button></nav>
    <main class="hall-scroll">
      <p v-if="notice" class="page-message">{{ notice }}</p><p v-if="errorText" class="page-error">{{ errorText }}</p>
      <template v-if="activeTab==='create'">
        <section v-if="settingsOpen" class="panel settings-panel"><div class="section-heading"><div><small>连接设置</small><h2>Atlas Cloud API</h2></div><span class="model-pill">{{ connectionMode==='web'?'网页直连':nativeApp?'App 直连':'需安装' }}</span></div><div class="connection-tabs"><button :class="{active:connectionMode==='web'}" @click="connectionMode='web'">网页直连</button><button :class="{active:connectionMode==='app'}" @click="connectionMode='app'">App 直连</button></div><label class="field"><span>接口地址</span><input v-model.trim="config.baseUrl" inputmode="url" placeholder="https://api.atlascloud.ai"></label><label class="field"><span>API Key</span><div class="input-action"><input v-model="apiKey" :type="showKey?'text':'password'" autocomplete="off" placeholder="apikey-..."><button @click="showKey=!showKey">{{ showKey?'隐藏':'显示' }}</button></div></label><label v-if="connectionMode==='web'" class="switch-row"><span><b>记住网页密钥</b><small>关闭时仅保留在当前页面会话</small></span><input v-model="rememberKey" type="checkbox"><i></i></label><p class="privacy-note">{{ connectionMode==='web'?'密钥、提示词和素材会由浏览器直接发送给 Atlas Cloud；公开部署请使用自己的后端代理。':'密钥保存在系统安全存储，请求由安装后的 App 发出。' }}</p><div class="settings-actions"><button @click="saveKey">保存连接</button><button @click="refreshBalance">查询余额</button></div><p v-if="balance" class="balance-line">当前余额 {{ balance.currency }} {{ Number.isFinite(balance.value)?balance.value.toFixed(4):'—' }}</p></section>

        <section class="panel model-summary"><div class="section-heading"><div><small>当前模型</small><h2>{{ selectedModel==='custom'?(customModel||'自定义模型'):selectedPreset?.name }}</h2><p>{{ selectedPreset?.description||'使用完整模型 ID 与模型专属 JSON 参数' }}</p></div><button class="secondary-button compact" @click="modelCenterOpen=true">选择模型</button></div><template v-if="selectedModel==='custom'"><label class="field"><span>完整模型 ID</span><input v-model.trim="customModel" placeholder="provider/model/task"></label><label class="field"><span>生成方式</span><select v-model="customWorkflow"><option value="text">文生视频</option><option value="image">图生视频</option><option value="reference">参考生成</option></select></label></template><p v-else class="model-id">{{ currentModelId||'尚未填写模型 ID' }}</p></section>
        <section class="panel create-section"><div class="section-heading"><div><small>视频描述</small><h2>描述画面、动作、镜头与声音</h2></div><span class="counter">{{ prompt.length }}/10000</span></div><textarea v-model="prompt" maxlength="10000" placeholder="例如：雨后的夜晚街道，人物撑伞缓慢走过霓虹灯，镜头从侧后方平稳跟随，环境声自然……"></textarea>
          <template v-if="workflow!=='text'"><div class="subheading"><span>{{ workflow==='image'?'起始图片':'参考素材' }}</span><small>本机上传会生成临时地址</small></div><div class="source-list"><div v-for="(_,index) in sourceUrls" :key="index" class="source-row"><input v-model.trim="sourceUrls[index]" inputmode="url" placeholder="https://..."><button aria-label="移除素材" @click="removeSource(index)">×</button></div></div><div class="source-actions"><button :disabled="sourceUrls.length>=8" @click="addSource">添加地址</button><label :class="{disabled:uploading}">{{ uploading?'正在上传…':'上传本机素材' }}<input type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,audio/*" :disabled="uploading" @change="uploadLocal"></label></div></template>
          <div class="parameter-grid"><label class="field"><span>时长（秒）</span><input v-model.number="config.duration" type="number" min="1" max="60" step="1"></label><label class="field"><span>分辨率</span><input v-model.trim="config.resolution" placeholder="例如 720p / 2K"></label><label class="field"><span>画面比例</span><select v-model="config.ratio"><option>16:9</option><option>9:16</option><option>1:1</option><option>4:3</option><option>3:4</option><option>21:9</option><option value="">由模型决定</option></select></label><label class="field"><span>作品集</span><input v-model.trim="project" maxlength="40" placeholder="默认作品集"></label></div>
          <button class="advanced-toggle" @click="advancedOpen=!advancedOpen"><span>高级控制与隐私保留</span><svg viewBox="0 0 24 24" :class="{open:advancedOpen}"><path d="m6 9 6 6 6-6"/></svg></button><div v-if="advancedOpen" class="advanced-body"><div class="parameter-grid"><label class="field"><span>Seed</span><div class="input-action"><input v-model="config.seed" type="number" min="0" step="1" placeholder="随机"><button @click="randomSeed">随机</button></div></label><label class="field"><span>作品保留（小时）</span><input v-model.number="config.objectExpirationHours" type="number" min="1" max="336"><small>远程结果最多 336 小时</small></label><label class="field"><span>任务记录保留（小时）</span><input v-model.number="config.requestRetentionHours" type="number" min="0" max="336"><small>0 表示任务完成后尽快删除记录</small></label></div><label v-if="selectedPreset?.promptExpansionField" class="switch-row"><span><b>提示词扩写</b><small>使用当前模型文档对应的参数名称</small></span><input v-model="config.promptExpansion" type="checkbox"><i></i></label><label v-if="selectedPreset?.watermarkField" class="switch-row"><span><b>生成水印</b><small>使用当前模型文档对应的参数名称</small></span><input v-model="config.watermark" type="checkbox"><i></i></label><label class="field"><span>模型专属参数（JSON）</span><textarea v-model="extraJson" rows="5" spellcheck="false" placeholder='{"audio": true}'></textarea><small>这里的同名字段会覆盖上方公共参数；未映射的模型特有能力也从这里传入。</small></label></div>
          <div class="generation-note"><span>{{ modelLabel(currentModelId) }}</span><span>{{ config.duration }} 秒</span><span>{{ config.resolution||'模型默认清晰度' }}</span><span>{{ config.ratio||'模型默认比例' }}</span><span>结果最多保留 {{ config.objectExpirationHours }} 小时</span></div><div class="cost-row"><div><small>本次费用</small><strong>{{ formatPrice(estimate) }}</strong></div><button :disabled="estimating||!canGenerate" @click="calculate()">{{ estimating?'计算中…':'更新费用' }}</button></div>
        </section>
        <p v-if="keyReady&&!apiKey.trim()" class="generate-hint">请先从右上角连接设置填写 Atlas Cloud API Key。</p><p v-else-if="connectionMode==='app'&&!nativeApp" class="generate-hint">App 直连只能在安装后的 Android 或 iOS App 中使用。</p><button class="generate-button" :disabled="!canGenerate" @click="requestGenerate"><i v-if="busy" class="spinner"></i>{{ busy?'正在提交…':'确认费用并生成' }}</button>
        <section v-if="activeTasks.length" class="panel running-section"><div class="section-heading"><div><small>正在进行</small><h2>{{ activeTasks.length }} 个 Atlas 任务</h2></div></div><div v-for="task in activeTasks" :key="task.id" class="running-card"><div class="running-indicator"><span></span></div><div class="task-copy"><strong>{{ statusLabel(task.status) }} · {{ task.progress }}%</strong><p>{{ task.input.prompt }}</p><small>{{ modelLabel(task.input.model) }} · {{ task.input.duration||'默认' }} 秒</small></div><button @click="pauseTask(task)">暂停</button></div></section>
      </template>
      <section v-else class="works-list"><section v-if="tasks.length" class="panel filter-panel"><label class="field"><span>作品集</span><select v-model="projectFilter"><option>全部</option><option v-for="name in projectNames" :key="name">{{ name }}</option></select></label></section><article v-for="task in visibleTasks" :key="task.id" class="work-card"><div class="work-media" :class="{portrait:task.input.ratio==='9:16'||task.input.ratio==='3:4'}"><video v-if="task.localWebUrl||outputUsable(task)" :src="task.localWebUrl||task.outputUrl" controls playsinline preload="metadata"></video><div v-else class="work-placeholder"><i v-if="['submitting','queued','processing','downloading'].includes(task.status)" class="spinner"></i><strong>{{ outputUsable(task)?statusLabel(task.status):task.outputUrl?'远程地址已过期':statusLabel(task.status) }}</strong><small v-if="task.progress">{{ task.progress }}%</small></div><span class="status-badge" :class="task.status">{{ statusLabel(task.status) }}</span></div><div class="work-info"><strong>{{ task.input.prompt }}</strong><p>{{ modelLabel(task.input.model) }} · {{ task.input.duration||'模型默认' }} 秒 · {{ task.input.resolution||'模型默认' }} · {{ formatTime(task.createdAt) }}</p><p>费用 {{ formatPrice(task.estimate) }}<template v-if="task.requestId"> · Request ID：{{ task.requestId }}</template></p><p v-if="task.outputExpiresAt&&!task.localFileUri" class="expiry-note">远程视频保留至 {{ formatTime(task.outputExpiresAt) }}，请及时下载。</p><p v-if="task.error" class="task-error">{{ task.error }}</p><div class="work-actions"><button v-if="task.localFileUri||outputUsable(task)" @click="downloadTask(task)">{{ task.localFileUri?'分享/保存':'下载' }}</button><button v-if="['paused','queued','processing'].includes(task.status)&&task.remoteId" @click="resumeTask(task)">继续查询</button><button @click="reuseTask(task)">复用参数</button><button class="danger" @click="deletingTask=task">删除</button></div></div></article><div v-if="!visibleTasks.length" class="empty-works"><svg viewBox="0 0 24 24"><path d="M4 6h16v12H4zM8 3v3m8-3v3M8 18v3m8-3v3"/></svg><h2>还没有 Atlas Cloud 作品</h2><p>选择模型、确认费用并生成，任务提交后可以离开这个页面。</p><button @click="activeTab='create'">开始创作</button></div></section>
    </main>

    <Transition name="sheet"><div v-if="modelCenterOpen" class="sheet-overlay model-overlay" @click.self="modelCenterOpen=false"><section class="model-sheet"><header><div><small>模型中心</small><h2>选择 Atlas Cloud 视频模型</h2></div><button class="close-small" @click="modelCenterOpen=false">×</button></header><input v-model="search" class="search-input" placeholder="搜索模型、厂商或能力"><div class="filter-strip"><select v-model="providerFilter"><option v-for="item in providers" :key="item">{{ item }}</option></select><select v-model="workflowFilter"><option value="全部">全部方式</option><option value="text">文生视频</option><option value="image">图生视频</option><option value="reference">参考生成</option></select><button :class="{active:favoritesOnly}" @click="favoritesOnly=!favoritesOnly">收藏</button></div><div class="model-list"><article v-for="item in visibleModels" :key="item.id" :class="{selected:selectedModel===item.id}" @click="chooseModel(item)"><div><strong>{{ item.name }}</strong><small>{{ item.provider }} · {{ item.workflow==='text'?'文生':item.workflow==='image'?'图生':'参考' }}</small><p>{{ item.description }}</p><span>{{ item.id }}</span></div><button aria-label="收藏模型" @click.stop="toggleFavorite(item.id)">{{ favorites.includes(item.id)?'★':'☆' }}</button></article><p v-if="!visibleModels.length" class="no-model">没有匹配的内置模型，可以使用自定义模型 ID。</p></div><button class="custom-model-button" @click="chooseCustom">使用自定义模型 ID</button></section></div></Transition>
    <Transition name="sheet"><div v-if="confirmInput" class="sheet-overlay" @click.self="confirmInput=null"><section class="confirm-sheet"><h2>确认提交生成</h2><p>{{ modelLabel(confirmInput.model) }} · {{ confirmInput.duration||'模型默认' }} 秒 · {{ confirmInput.resolution||'模型默认清晰度' }}</p><div class="confirm-price"><small>预计费用</small><strong>{{ formatPrice(estimate) }}</strong><span v-if="estimate?.estimated">实际扣费可能因输出视频 Token 略有变化</span><span v-else-if="!estimate">费用暂时无法获取，请确认账户预算后再提交</span></div><div class="confirm-actions"><button @click="confirmInput=null">返回检查</button><button class="primary" :disabled="busy" @click="confirmGenerate">确认生成</button></div></section></div></Transition>
    <Transition name="sheet"><div v-if="deletingTask" class="sheet-overlay" @click.self="deletingTask=null"><section class="confirm-sheet"><h2>删除本地作品记录？</h2><p>会删除 App 内已保存的文件，但不会取消或删除 Atlas Cloud 云端任务。</p><div class="confirm-actions"><button @click="deletingTask=null">保留</button><button class="danger-fill" @click="confirmDelete">删除</button></div></section></div></Transition>
  </div>
</template>

